import SwiftUI
import Charts
import WeatherCore
struct Sample:Identifiable {let id:Int;let date:Date;let value:Double}
struct ObservatoryView:View {
 @ObservedObject var model:WeatherModule
 var settingsOnly=false
 @State private var metric="Temperature"
 private let teal=Color(red:0.48,green:0.85,blue:0.79)
 var body:some View {
 VStack(spacing:0){
  HStack(spacing:14){Image(systemName:"cloud.sun.fill").font(.system(size:32)).symbolRenderingMode(.palette).foregroundStyle(.yellow,teal);VStack(alignment:.leading){Text("Weather Observatory").font(.title2.bold());Text(model.preferences.automatic && !model.located ? model.locationMessage:"\(model.place.name) · \(model.place.region)").foregroundStyle(.secondary)};Spacer();Picker("Units",selection:Binding(get:{model.unit},set:{model.setUnit($0)})){Text("°F").tag("F");Text("°C").tag("C")}.pickerStyle(.segmented).labelsHidden().frame(width:95);Button{model.refresh()}label:{Image(systemName:"arrow.clockwise")}.disabled(!model.loading.isEmpty);if !model.loading.isEmpty{ProgressView().controlSize(.small)}}.padding(22)
  HStack{Picker("View",selection:$model.tab){ForEach(settingsOnly ? ["Location","Sources","Alerts"]:["Now","Forecast","Marine","Map","Alerts","Sources","Location"],id:\.self){Text($0)}}.pickerStyle(.segmented).labelsHidden()}.padding(.horizontal,22).padding(.bottom,16)
  if model.preferences.automatic && !model.located && model.tab != "Location" {VStack(spacing:20){Image(systemName:"location.circle").font(.system(size:64)).foregroundStyle(teal);Text("Weather where you are").font(.largeTitle.bold());Text(model.locationMessage).foregroundStyle(.secondary);Button("Set up location"){model.tab="Location"}.buttonStyle(.borderedProminent)}.frame(maxWidth:.infinity,maxHeight:.infinity)}
  else {ScrollView {Group{switch model.tab{case "Now":now;case "Forecast":forecast;case "Marine":marine;case "Map":maps;case "Alerts":alerts;case "Sources":sources;default:location}}.padding(.horizontal,22).padding(.bottom,22)}}
  HStack{Text(model.status);Spacer();Text("Weather Observatory · 0.3.0")}.font(.caption).foregroundStyle(.secondary).padding(12).background(.black.opacity(0.15))
 }.background(Color(red:0.045,green:0.075,blue:0.115)).preferredColorScheme(.dark)
 }
 private var now:some View{VStack(alignment:.leading,spacing:18){
  HStack(alignment:.top,spacing:18){
   VStack(alignment:.leading,spacing:10){Text("CURRENT FORECAST").font(.caption.bold()).foregroundStyle(teal);HStack{Text(model.currentTemp+"°").font(.system(size:74,weight:.light,design:.rounded));Spacer();Image(systemName:Display.symbol(Display.number(model.current["weather_code"]))).symbolRenderingMode(.multicolor).font(.system(size:60))};Text(model.condition).font(.title2);Text("Valid "+Display.time(Display.number(model.current["time"]),zone:model.place.timezone,format:"EEE h:mm a")).foregroundStyle(.secondary);Text(model.source("weather")+" · "+model.age("weather")).font(.caption).foregroundStyle(.secondary)}.padding(24).frame(maxWidth:.infinity,alignment:.leading).background(LinearGradient(colors:[Color(red:0.09,green:0.25,blue:0.31),Color(red:0.07,green:0.13,blue:0.22)],startPoint:.topLeading,endPoint:.bottomTrailing),in:RoundedRectangle(cornerRadius:20))
   LazyVGrid(columns:[GridItem(.flexible()),GridItem(.flexible())],spacing:12){metricCard("Feels like",Display.temperature(Display.number(model.current["apparent_temperature"]),unit:model.unit)+"°","thermometer.medium");metricCard("Wind",Display.wind(Display.number(model.current["wind_speed_10m"]),unit:model.unit)+(model.unit=="F" ? " mph":" km/h"),"wind");metricCard("Humidity",Display.value(Display.number(model.current["relative_humidity_2m"]))+"%","humidity");metricCard("US AQI",Display.value(model.number("air","current","us_aqi")),"aqi.medium")}.frame(maxWidth:.infinity)
  }
  errorLabel("weather");hourChart
  HStack{metricCard("Wind gusts",Display.wind(Display.number(model.current["wind_gusts_10m"]),unit:model.unit)+(model.unit=="F" ? " mph":" km/h"),"wind");metricCard("Pressure",Display.value(Display.number(model.current["pressure_msl"]))+" hPa","barometer");metricCard("Cloud cover",Display.value(Display.number(model.current["cloud_cover"]))+"%","cloud")}
  Text(model.weather["notice"] as? String ?? "Current conditions are model estimates, not a station observation.").font(.caption).foregroundStyle(.secondary)
  Text("Air: CAMS via Open-Meteo · modeled US AQI · "+model.age("air")).font(.caption).foregroundStyle(.secondary);errorLabel("air")
 }}
 private func metricCard(_ name:String,_ value:String,_ symbol:String)->some View{VStack(alignment:.leading,spacing:14){Label(name,systemImage:symbol).font(.callout).foregroundStyle(.secondary);Text(value).font(.system(size:25,weight:.medium,design:.rounded)).foregroundStyle(teal).monospacedDigit()}.frame(maxWidth:.infinity,alignment:.leading).padding(18).background(.white.opacity(0.045),in:RoundedRectangle(cornerRadius:14))}
 private func errorLabel(_ name:String)->some View{Group{if let error=model.errors[name]{Label(error,systemImage:"exclamationmark.triangle").font(.callout).foregroundStyle(.orange)}}}
 private var samples:[Sample]{let key=metric=="Temperature" ? "temperature_2m":metric=="Wind" ? "wind_speed_10m":"precipitation";let times=model.row("weather","hourly","time"),values=model.row("weather","hourly",key);return times.enumerated().compactMap{i,t in guard let t,i<values.count,let value=values[i],t>=Date().timeIntervalSince1970-3600 else{return nil};let converted=metric=="Temperature" ? (model.unit=="F" ? value*9/5+32:value):metric=="Wind" ? (model.unit=="F" ? value/1.609344:value):(model.unit=="F" ? value/25.4:value);return Sample(id:i,date:Date(timeIntervalSince1970:t),value:converted)}.prefix(48).map{$0}}
 private var hourChart:some View{VStack(alignment:.leading,spacing:14){HStack{Text("Next 48 hours").font(.headline);Spacer();Picker("Chart",selection:$metric){Text("Temperature").tag("Temperature");Text("Wind").tag("Wind");Text("Rain").tag("Rain")}.pickerStyle(.segmented).frame(width:310)};if samples.isEmpty{Text("Hourly values unavailable").foregroundStyle(.secondary).frame(height:160)}else{Chart(samples){sample in if metric=="Rain"{BarMark(x:.value("Time",sample.date),y:.value("Rain",sample.value)).foregroundStyle(teal)}else{LineMark(x:.value("Time",sample.date),y:.value(metric,sample.value)).foregroundStyle(teal).lineStyle(.init(lineWidth:2.5))}}.chartXAxis{AxisMarks(values:.stride(by:.hour,count:6)){value in AxisGridLine();AxisValueLabel{if let date=value.as(Date.self){Text(Display.time(date.timeIntervalSince1970,zone:model.place.timezone))}}}}.frame(height:180)};Text((metric=="Temperature" ? "°"+model.unit:metric=="Wind" ? (model.unit=="F" ? "mph":"km/h"):(model.unit=="F" ? "inches/hour":"mm/hour"))+" · "+model.place.timezone).font(.caption).foregroundStyle(.secondary)}.padding(20).background(.white.opacity(0.035),in:RoundedRectangle(cornerRadius:16))}
 private var forecast:some View{VStack(alignment:.leading,spacing:18){hourChart;Text("Seven-day outlook").font(.title3.bold());let times=model.row("weather","daily","time");ForEach(Array(times.enumerated()),id:\.offset){i,t in HStack{Text(Display.time(t,zone:model.place.timezone,format:"EEE, MMM d")).frame(width:140,alignment:.leading);Image(systemName:Display.symbol(at("weather","daily","weather_code",i))).foregroundStyle(teal).frame(width:35);Text(Display.condition(at("weather","daily","weather_code",i))).frame(maxWidth:.infinity,alignment:.leading);Text(Display.temperature(at("weather","daily","temperature_2m_max",i),unit:model.unit)+"°").font(.title3.bold()).frame(width:55);Text(Display.temperature(at("weather","daily","temperature_2m_min",i),unit:model.unit)+"°").foregroundStyle(.secondary).frame(width:55);Label(Display.value(at("weather","daily","precipitation_probability_max",i))+"%",systemImage:"drop").frame(width:85)}.padding(12).background(.white.opacity(0.04),in:RoundedRectangle(cornerRadius:10))};errorLabel("weather");Text(model.weather["precipitationNote"] as? String ?? "Precipitation probabilities and daily summaries follow the source forecast.").font(.caption).foregroundStyle(.secondary)}}
 private func at(_ feed:String,_ group:String,_ key:String,_ index:Int)->Double?{let values=model.row(feed,group,key);return index<values.count ? values[index]:nil}
 private var marine:some View{VStack(alignment:.leading,spacing:18){Text("Ocean & tides").font(.title.bold());Text("Ocean grid forecasts are separate from land weather. Waves are significant wave heights.").foregroundStyle(.secondary);let data=model.feeds["marine"] ?? [:];if let lat=Display.number(data["latitude"]),let lon=Display.number(data["longitude"]){Text("Ocean model cell: "+Display.value(Display.distance(model.place,lat:lat,lon:lon))+" km from selected place").font(.caption).foregroundStyle(.secondary)};HStack{metricCard("Waves",Display.wave(model.number("marine","current","wave_height"),unit:model.unit)+(model.unit=="F" ? " ft":" m"),"water.waves");metricCard("Period",Display.value(model.number("marine","current","wave_period"),digits:1)+" s","waveform.path");metricCard("Swell",Display.wave(model.number("marine","current","swell_wave_height"),unit:model.unit)+(model.unit=="F" ? " ft":" m"),"water.waves")};errorLabel("marine");Text(model.source("marine")+" · "+model.age("marine")).font(.caption).foregroundStyle(.secondary)
  let times=model.row("marine","hourly","time");let points=times.enumerated().compactMap{i,t->Sample? in guard let t,t>=Date().timeIntervalSince1970,let value=at("marine","hourly","wave_height",i) else{return nil};return Sample(id:i,date:Date(timeIntervalSince1970:t),value:model.unit=="F" ? value*3.28084:value)}.prefix(48)
  Chart(Array(points)){p in LineMark(x:.value("Time",p.date),y:.value("Waves",p.value)).foregroundStyle(teal)}.chartXAxis{AxisMarks(values:.stride(by:.hour,count:12)){value in AxisGridLine();AxisValueLabel{if let date=value.as(Date.self){Text(Display.time(date.timeIntervalSince1970,zone:model.place.timezone,format:"EEE ha"))}}}}.frame(height:170)
  Divider();Text("Tide predictions · MLLW").font(.title3.bold());let tide=model.feeds["tides"] ?? [:];let station=tide["station"] as? [String:Any] ?? [:];Text(station["name"] as? String ?? "No nearby reference station received").foregroundStyle(.secondary);let events=(tide["events"] as? [[String:Any]] ?? []).filter{(Display.number($0["time"]) ?? 0)>Date().timeIntervalSince1970}.prefix(8)
  ForEach(Array(events.enumerated()),id:\.offset){_,event in HStack{Text(event["type"] as? String == "H" ? "High tide":"Low tide");Spacer();Text(Display.time(Display.number(event["time"]),zone:model.place.timezone,format:"EEE h:mm a"));Text(Display.wave(Display.number(event["height"]),unit:model.unit)+(model.unit=="F" ? " ft":" m")).frame(width:100)}};errorLabel("tides");Text(model.source("tides")+" · "+model.age("tides")).font(.caption).foregroundStyle(.secondary)
 }}
 private var maps:some View{VStack(alignment:.leading,spacing:12){Group { if model.detailVisible {WeatherMap(model:model)} else {Color.clear} }.frame(height:470).clipShape(RoundedRectangle(cornerRadius:14));Text("Observed radar and infrared imagery keep their own timestamps. Transparent radar tiles can mean no coverage; they are not an all-clear.").font(.caption).foregroundStyle(.secondary);errorLabel("radar");errorLabel("satellite");Text("Google WeatherNext, Earth Engine and Google satellite basemaps need a separate authorized plugin connection.").font(.caption).foregroundStyle(.secondary)}}
 private var alerts:some View{VStack(alignment:.leading,spacing:16){Text("Official alerts").font(.title.bold());let data=model.feeds["alerts"];let rows=data?["alerts"] as? [[String:Any]] ?? [];if data?["supported"] as? Bool == false{Text("NWS point alerts are not supported in this country.")}else if data != nil && rows.isEmpty && model.errors["alerts"] == nil{Text("No active alerts returned for this point. Marine zones may have separate advisories.")}else if data == nil {Text("Alert status unavailable.")};ForEach(Array(rows.enumerated()),id:\.offset){_,row in VStack(alignment:.leading,spacing:10){Text(row["event"] as? String ?? "Alert").font(.title3.bold()).foregroundStyle(.orange);Text(row["headline"] as? String ?? "");Text(row["description"] as? String ?? "").textSelection(.enabled);if let instruction=row["instruction"] as? String{Text(instruction).bold()}}.padding(18).frame(maxWidth:.infinity,alignment:.leading).background(.orange.opacity(0.07),in:RoundedRectangle(cornerRadius:14))};errorLabel("alerts");Text(model.source("alerts")+" · "+model.age("alerts")).font(.caption).foregroundStyle(.secondary);Divider();Text("Tropical cyclones").font(.title3.bold());let storms=model.feeds["cyclones"]?["storms"] as? [[String:Any]] ?? [];ForEach(Array(storms.enumerated()),id:\.offset){_,storm in VStack(alignment:.leading){Text(storm["name"] as? String ?? "Storm").bold();Text((storm["classification"] as? String ?? "")+" · "+(storm["updated"] as? String ?? ""))}};if storms.isEmpty{Text(model.feeds["cyclones"] == nil ? "Cyclone data unavailable":"No active storms returned for the Atlantic / eastern and central Pacific feeds.")};errorLabel("cyclones")}}
 private var sources:some View{VStack(alignment:.leading,spacing:18){WindySettings(model:model);Text("Source health").font(.title.bold());ForEach(model.feedNames,id:\.self){feed in VStack(alignment:.leading,spacing:5){HStack{Text(model.source(feed)).bold();Spacer();Text(model.age(feed)).foregroundStyle(.secondary)};Text(model.errors[feed] ?? (model.loading.contains(feed) ? "Refreshing…":model.feeds[feed] == nil ? "Not received":"Received")).foregroundStyle(model.errors[feed] == nil ? Color.secondary:Color.orange);if feed=="weather",let issued=model.weather["issuedAt"] as? String{Text("Model issued: "+issued).font(.caption)}}.padding(14).background(.white.opacity(0.035),in:RoundedRectangle(cornerRadius:10))};Text("Data: NOAA/NWS and CO-OPS; Open-Meteo and MET Norway, CC BY 4.0; CAMS via Open-Meteo; RainViewer radar; OpenStreetMap contributors. Maps retain provider attribution.").font(.caption).foregroundStyle(.secondary);Text("WeatherNext / Earth Engine: not connected. The website’s Google credentials are not bundled or reused. Tracking layers and 3D atmosphere are not included in this first module release.").foregroundStyle(.secondary)}}
 private var location:some View{VStack(alignment:.leading,spacing:18){Text("Your location").font(.title.bold());Toggle("Use this Mac’s location",isOn:Binding(get:{model.preferences.automatic},set:{model.setAutomatic($0)}));Text("macOS supplies your location. Rounded coordinates are sent directly to the weather providers for forecasts. You can choose a different place below.").foregroundStyle(.secondary);if model.preferences.automatic{Text(model.locationMessage);Button("Try location again"){model.locate()}};Divider();HStack{TextField("Search for a city or place",text:$model.query).onSubmit{model.search()};Button("Search"){model.search()}.disabled(model.loading.contains("search"))};if !model.searchError.isEmpty{Text(model.searchError).foregroundStyle(.orange)};ForEach(model.results){place in Button("\(place.name), \(place.region) · \(place.country)"){model.select(place)}.buttonStyle(.bordered)};Text("Saved places").font(.headline);ForEach(Place.presets){place in Button("\(place.name) · \(place.region)"){model.select(place)}};Text("Selected timezone: "+model.place.timezone).font(.caption).foregroundStyle(.secondary)}}
}
